{"cmd":"python - <<'PY'
from csv import DictReader

def parse_decimal(text: str) -> float:
    return float(text.replace(',', '.'))

products = {}
with open('/app/dataset/product_catalog.csv', newline='') as f:
    for row in DictReader(f):
        item = {
            'name': row['name'],
            'unit_price': parse_decimal(row['unit_price']),
            'unit_weight_kg': parse_decimal(row['unit_weight_kg']),
        }
        products[row['product_id']] = item
        products[row['ean_code']] = item

total = 0
mismatches = []
with open('/app/dataset/warehouse_dispatches.csv', newline='') as f:
    for row in DictReader(f):
        item = products[row['product_id']]
        qty = int(row['quantity'])
        total += qty * item['unit_price']
        calc_weight = qty * item['unit_weight_kg']
        total_weight = parse_decimal(row['total_weight_kg'])
        if abs(calc_weight - total_weight) > 1e-9:
            mismatches.append((row['dispatch_id'], row['product_id'], calc_weight, total_weight))
print('total all dispatches', total)
print('weight mismatches', len(mismatches))
print(mismatches[:5])
